const responseText = $json.content[0].text;
let parsed;
try {
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : responseText);
} catch(e) {
  parsed = { meal_type: 'unknown', items: [], summary: 'Failed to parse food data: ' + responseText.substring(0, 200) };
}

const today = new Date().toISOString().split('T')[0];

const items = (parsed.items || []).map(item => ({
  json: {
    date: today,
    meal_type: parsed.meal_type || 'snack',
    item: item.item,
    weight_g: item.weight_g || 0,
    calories: item.calories || 0,
    protein_g: item.protein_g || 0,
    carbs_g: item.carbs_g || 0,
    fat_g: item.fat_g || 0,
    source: 'telegram'
  }
}));

if (items.length === 0) {
  items.push({ json: { date: today, meal_type: 'unknown', item: 'parse_error', weight_g: 0, calories: 0, protein_g: 0, carbs_g: 0, fat_g: 0, source: 'telegram' } });
}

items[0].json._summary = parsed.summary || 'Food logged';
items[0].json._fullResponse = responseText;

return items;

const memoryRows = $('Read Memory Text').all().map(i => i.json);
const userMessage = $('Set Text').item.json.userMessage;
const chatId = $('Set Text').item.json.chatId;

const sorted = memoryRows
  .filter(r => r.timestamp)
  .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
  .slice(0, 10)
  .reverse();

const messages = sorted.map(r => ({
  role: r.role || 'user',
  content: String(r.content || '')
}));

messages.push({ role: 'user', content: userMessage });

return [{ json: { messages, userMessage, chatId } }];

