const allMeals = $('Read All Meals').all().map(i => i.json);
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sevenDaysAgoStr = sevenDaysAgo.toISOString().split('T')[0];

const recentMeals = allMeals.filter(m => m.date && m.date >= sevenDaysAgoStr);

if (recentMeals.length === 0) {
  return [{ json: { hasMeals: false, prompt: 'No meals logged in the past 7 days.' } }];
}

let mealText = 'Here are my meals from the past 7 days:\n\n';
const byDate = {};
for (const m of recentMeals) {
  if (!byDate[m.date]) byDate[m.date] = [];
  byDate[m.date].push(m);
}

for (const date of Object.keys(byDate).sort()) {
  mealText += date + ':\n';
  for (const m of byDate[date]) {
    mealText += '  ' + (m.meal_type || '?') + ': ' + (m.item || '?') + ' ' + (m.weight_g || 0) + 'g — ' + (m.calories || 0) + ' cal, P:' + (m.protein_g || 0) + 'g C:' + (m.carbs_g || 0) + 'g F:' + (m.fat_g || 0) + 'g\n';
  }
  mealText += '\n';
}

mealText += 'Please generate my weekly nutrition summary.';

return [{ json: { hasMeals: true, prompt: mealText, mealCount: recentMeals.length } }];

